package com.gogleox.scrip.api;

import com.gogleox.scrip.account.*;
import com.gogleox.scrip.ledger.*;
import com.gogleox.scrip.organization.*;
import com.gogleox.scrip.payment.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Predicate;

/** Stable API implementation that delegates every mutation to the durable ledger services. */
public final class DefaultEconomyService implements EconomyService {
    private final AccountLedger ledger; private final PaymentService payments; private final TrustedRewardSourceRegistry rewards; private final Predicate<UUID> administrators; private final List<EconomyEventListener> listeners=new CopyOnWriteArrayList<>();
    public DefaultEconomyService(AccountLedger ledger, TrustedRewardSourceRegistry rewards, Predicate<UUID> administrators){this.ledger=Objects.requireNonNull(ledger);this.payments=new PaymentService(ledger);this.rewards=Objects.requireNonNull(rewards);this.administrators=Objects.requireNonNull(administrators);}
    @Override public int apiVersion(){return API_VERSION;}
    @Override public CompletionStage<Optional<AccountSnapshot>> personalAccount(UUID playerId){return CompletableFuture.completedFuture(ledger.findPersonal(playerId));}
    @Override public CompletionStage<Optional<AccountSnapshot>> account(AccountId accountId){return CompletableFuture.completedFuture(ledger.findAccount(accountId));}
    @Override public CompletionStage<TransferPreviewResult> previewTransfer(TransferPreviewRequest request){PaymentResult result=payments.preview(request.actorId(),request.source(),request.destination(),request.amount());return CompletableFuture.completedFuture(new TransferPreviewResult(mapPreview(result.status()),result.preview()));}
    @Override public CompletionStage<EconomyTransactionResult> executeTransfer(TransferExecutionRequest request){TransferOutcome outcome=payments.executeAuthorizedPreview(request.actorId(),request.preview());EconomyTransactionResult mapped=EconomyTransactionResult.from(outcome);if(outcome.status()==TransferOutcome.Status.SUCCESS)publish(EconomyPostCommitEvent.Kind.TRANSFER,outcome.operationId(),outcome.durableSequence());return CompletableFuture.completedFuture(mapped);}
    @Override public CompletionStage<EconomyTransactionResult> adjust(AdministrativeAdjustmentRequest request){if(!administrators.test(request.actorId()))return CompletableFuture.completedFuture(new EconomyTransactionResult(TransferOutcome.Status.UNAUTHORIZED,request.operationId(),OptionalLong.empty(),false));return ledger.adjustAdministratively(new AdminAdjustmentRequest(request.operationId(),request.accountId(),request.delta(),request.reason(),AuditActor.player(request.actorId(),"integration"))).thenApply(outcome->{EconomyTransactionResult result=EconomyTransactionResult.from(outcome);if(outcome.status()==TransferOutcome.Status.SUCCESS)publish(EconomyPostCommitEvent.Kind.ADMIN_ADJUSTMENT,outcome.operationId(),outcome.durableSequence());return result;});}
    @Override public CompletionStage<IntegrationRewardResponse> issueReward(IntegrationRewardRequest request){Optional<TrustedRewardSource> source=rewards.find(request.sourceId());if(source.isEmpty())return CompletableFuture.completedFuture(new IntegrationRewardResponse(IntegrationRewardResponse.Status.UNAUTHORIZED_SOURCE,null,OptionalLong.empty()));if(request.amount()<=0)return CompletableFuture.completedFuture(new IntegrationRewardResponse(IntegrationRewardResponse.Status.INVALID,null,OptionalLong.empty()));if(request.amount()>source.get().maximumAmount())return CompletableFuture.completedFuture(new IntegrationRewardResponse(IntegrationRewardResponse.Status.LIMIT_EXCEEDED,null,OptionalLong.empty()));Optional<AccountSnapshot> account=ledger.findPersonal(request.recipientId());if(account.isEmpty())return CompletableFuture.completedFuture(new IntegrationRewardResponse(IntegrationRewardResponse.Status.UNKNOWN_PLAYER,null,OptionalLong.empty()));return ledger.issueIntegrationReward(UUID.randomUUID(),request.sourceId(),request.claimId(),account.get().id(),request.recipientId(),request.amount()).thenApply(result->{IntegrationRewardResponse response=new IntegrationRewardResponse(mapReward(result.status()),result.operationId(),result.durableSequence());if(result.status()==IntegrationRewardResult.Status.ISSUED)publish(EconomyPostCommitEvent.Kind.INTEGRATION_REWARD,result.operationId(),result.durableSequence());return response;});}
    @Override public CompletionStage<List<TransactionRecord>> history(AccountId accountId,int limit){if(limit<1||limit>100)return CompletableFuture.completedFuture(List.of());return CompletableFuture.completedFuture(ledger.history(accountId).stream().limit(limit).toList());}
    @Override public CompletionStage<Optional<OrganizationSnapshot>> organization(OrganizationId id){return CompletableFuture.completedFuture(ledger.findOrganization(id));}
    @Override public CompletionStage<ActorAuthorization> authorize(UUID actor,AccountId account,EconomyPermission permission){boolean allowed=switch(permission){case ADMIN_ADJUST->administrators.test(actor);case ISSUE_REWARD->false;case TRANSFER->ledger.canInitiatePayment(actor,account);case VIEW->ledger.accessibleAccounts(actor).stream().anyMatch(access->access.accountId().equals(account));};return CompletableFuture.completedFuture(new ActorAuthorization(allowed,allowed?"":"server authorization denied"));}
    public void addPostCommitListener(EconomyEventListener listener){listeners.add(Objects.requireNonNull(listener));}
    public void removePostCommitListener(EconomyEventListener listener){listeners.remove(listener);}
    private void publish(EconomyPostCommitEvent.Kind kind,UUID operation,OptionalLong sequence){if(operation==null)return;EconomyPostCommitEvent event=new EconomyPostCommitEvent(kind,operation,sequence,Instant.now());for(EconomyEventListener listener:listeners)listener.afterCommit(event);}
    private static TransferPreviewResult.Status mapPreview(PaymentResult.Status status){return switch(status){case PREVIEW_READY->TransferPreviewResult.Status.READY;case UNAUTHORIZED,FROZEN->TransferPreviewResult.Status.UNAUTHORIZED;case UNKNOWN_ACCOUNT->TransferPreviewResult.Status.UNKNOWN_ACCOUNT;case INSUFFICIENT_FUNDS->TransferPreviewResult.Status.INSUFFICIENT_FUNDS;case INVALID_AMOUNT->TransferPreviewResult.Status.INVALID;default->TransferPreviewResult.Status.FAILURE;};}
    private static TransferOutcome.Status mapTransfer(PaymentResult.Status status){return switch(status){case EXECUTED->TransferOutcome.Status.SUCCESS;case UNAUTHORIZED->TransferOutcome.Status.UNAUTHORIZED;case FROZEN->TransferOutcome.Status.FROZEN_ACCOUNT;case INSUFFICIENT_FUNDS->TransferOutcome.Status.INSUFFICIENT_FUNDS;case UNKNOWN_ACCOUNT->TransferOutcome.Status.UNKNOWN_ACCOUNT;case POLICY_CHANGED->TransferOutcome.Status.POLICY_CHANGED;case STORAGE_FAILURE->TransferOutcome.Status.STORAGE_FAILURE;default->TransferOutcome.Status.OPERATION_CONFLICT;};}
    private static IntegrationRewardResponse.Status mapReward(IntegrationRewardResult.Status status){return switch(status){case ISSUED->IntegrationRewardResponse.Status.ISSUED;case DUPLICATE->IntegrationRewardResponse.Status.DUPLICATE;case CONFLICT->IntegrationRewardResponse.Status.CONFLICT;case INVALID->IntegrationRewardResponse.Status.INVALID;case UNKNOWN_PLAYER->IntegrationRewardResponse.Status.UNKNOWN_PLAYER;case STORAGE_FAILURE->IntegrationRewardResponse.Status.STORAGE_FAILURE;};}
}
